{
  "findings": [
    {
      "check_id": "CKV_AWS_290",
      "title": "Ensure IAM policies does not allow write access without constraints",
      "resource": "aws_iam_policy.privesc-ssmStartSession-policy",
      "severity": "MEDIUM",
      "explanation": "The policy allows write actions (ssm:StartSession, ssm:TerminateSession, ssm:ResumeSession) without resource constraints."
    },
    {
      "check_id": "CKV_AWS_355",
      "title": "Ensure no IAM policies documents allow '*' as a statement's resource for restrictable actions",
      "resource": "aws_iam_policy.privesc-ssmStartSession-policy",
      "severity": "MEDIUM",
      "explanation": "The policy allows restrictable actions (ssm:StartSession, ssm:TerminateSession, ssm:ResumeSession) on all resources ('*')."
    }
  ],
  "patched_code": "resource "aws_iam_policy" "privesc-ssmStartSession-policy" {
  name        = "privesc-ssmStartSession-policy"
  path        = "/"
  description = "Allows privesc via targeted ssm"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ssm:DescribeSessions",
          "ssm:GetConnectionStatus",
          "ssm:DescribeInstanceProperties",
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action = [
          "ssm:StartSession",
          "ssm:TerminateSession",
          "ssm:ResumeSession"
        ]
        Resource = "arn:aws:ec2:*:*:instance/*"
      },
    ]
  })
}",
  "fix_summary": "Split the policy into two statements: one for actions that require '*' and another for actions that can be restricted to specific resources (EC2 instances)."
}
